-- Preserve participant facts; on-site review uses the actual venue.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
lock table machimoa_review.review_classifications,machimoa_review.review_classification_history,machimoa_review.source_item_content_filters,machimoa_review.source_item_program_facts,machimoa_review.myseoul_residence_reviews,machimoa_review.myseoul_fact_edits in share row exclusive mode;
do $$ begin
if to_regprocedure('machimoa_review.classification_validate(jsonb,jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.classification_validate(jsonb,jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'1e01b8a6abd3907752d6298aacdf406becb5694a85b95c88f6c86f11c195e2cf' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.classification_validate(jsonb,jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'classification_flow_predecessor_changed: %','machimoa_review.classification_validate(jsonb,jsonb)';end if;
if to_regprocedure('machimoa_review.classification_reasons(uuid,jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.classification_reasons(uuid,jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'85a3d04d2359a278ee6a34d7717ed53fcad5fa4a12abb9f6fa01a545f31210af' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.classification_reasons(uuid,jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'classification_flow_predecessor_changed: %','machimoa_review.classification_reasons(uuid,jsonb)';end if;
if to_regclass('machimoa_review.classification_flow_install') is not null then raise exception 'classification_flow_already_installed';end if;
end $$;
create table machimoa_review.classification_flow_install(singleton boolean primary key check(singleton),dirty boolean not null default false,backup jsonb not null);
alter table machimoa_review.classification_flow_install enable row level security;
revoke all on machimoa_review.classification_flow_install from public,anon,authenticated,service_role;
insert into machimoa_review.classification_flow_install values(true,false,'{"machimoa_review.classification_validate(jsonb,jsonb)": "CREATE OR REPLACE FUNCTION machimoa_review.classification_validate(f jsonb, d jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''''\nAS $function$\ndeclare cat text;key text;g jsonb;o jsonb;start_day text;end_day text;\nbegin\n if f is null or jsonb_typeof(f)<>''object'' or (select array_agg(k order by k) from jsonb_object_keys(f) k) is distinct from array[''category'',''deadlineKind'',''deadlineOn'',''delivery'',''eventEnd'',''eventStart'',''evidence'',''foreignEligibility'',''productType'',''regions'',''scope''] then raise sqlstate ''PT422'' using message=''classification_invalid_facts'';end if;\n foreach key in array array[''category'',''deadlineKind'',''deadlineOn'',''delivery'',''eventEnd'',''eventStart'',''evidence'',''foreignEligibility'',''productType'',''scope''] loop\n if jsonb_typeof(f->key)<>''string'' or f->>key ~ ''[<>]'' then raise sqlstate ''PT422'' using message=''classification_invalid_text'';end if;end loop;\n cat:=f->>''category'';\n if cat not in (''policy'',''program'',''event'',''youth_space'',''living'') or f->>''productType'' not in (''event_program'',''policy_reference'',''living_guide'') or f->>''delivery'' not in (''online'',''offline'',''hybrid'') or f->>''scope'' not in (''nationwide'',''specific'',''unknown'') or f->>''foreignEligibility'' not in (''eligible'',''ineligible'',''unknown'') or char_length(f->>''evidence'')>500 then raise sqlstate ''PT422'' using message=''classification_missing_facts'';end if;\n if jsonb_typeof(f->''regions'')<>''array'' or jsonb_array_length(f->''regions'')>17 or exists(select 1 from jsonb_array_elements(f->''regions'') v where jsonb_typeof(v)<>''string'' or v#>>''{}'' not in (''11'',''26'',''27'',''28'',''29'',''30'',''31'',''36'',''41'',''42'',''43'',''44'',''45'',''46'',''47'',''48'',''50'')) or (select count(distinct v) from jsonb_array_elements(f->''regions'') v)<>jsonb_array_length(f->''regions'') then raise sqlstate ''PT422'' using message=''classification_invalid_regions'';end if;\n if f->>''scope''<>''specific'' and jsonb_array_length(f->''regions'')<>0 or f->>''scope''=''specific'' and jsonb_array_length(f->''regions'')=0 then raise sqlstate ''PT422'' using message=''classification_invalid_regions'';end if;\n if f->>''productType''<>''living_guide'' and (f->>''scope''=''unknown'' or char_length(btrim(f->>''evidence''))=0) or f->>''productType''=''policy_reference'' and f->>''foreignEligibility''=''unknown'' then raise sqlstate ''PT422'' using message=''classification_missing_evidence'';end if;\n g:=machimoa_review.classification_gate(f);perform machimoa_review.validate_gate_facts(f->>''productType'',g);\n if cat=''program'' and f->>''deadlineKind'' is distinct from ''fixed'' then raise sqlstate ''PT422'' using message=''classification_invalid_dates'';end if;\n if cat in (''policy'',''program'') then\n if f->>''deadlineKind'' not in (''fixed'',''none'',''closed'') or f->>''eventStart''<>'''' or f->>''eventEnd''<>'''' then raise sqlstate ''PT422'' using message=''classification_invalid_dates'';end if;\n if f->>''deadlineKind''=''fixed'' then perform machimoa_review.content_filter_day(f->>''deadlineOn'');elsif f->>''deadlineOn''<>'''' then raise sqlstate ''PT422'' using message=''classification_invalid_dates'';end if;\n elsif cat=''event'' then\n perform machimoa_review.content_filter_day(f->>''eventStart'');perform machimoa_review.content_filter_day(f->>''eventEnd'');\n if f->>''eventStart''>f->>''eventEnd'' or f->>''deadlineKind''<>'''' or f->>''deadlineOn''<>'''' then raise sqlstate ''PT422'' using message=''classification_invalid_dates'';end if;\n elsif f->>''deadlineKind''<>'''' or f->>''deadlineOn''<>'''' or f->>''eventStart''<>'''' or f->>''eventEnd''<>'''' then raise sqlstate ''PT422'' using message=''classification_invalid_dates'';end if;\n if cat in (''program'',''event'',''youth_space'') then\n perform machimoa_review.content_filter_validate(d);\n if d->>''category'' is distinct from cat or cardinality(machimoa_review.classification_filter_missing(d))<>0 then raise sqlstate ''PT422'' using message=''classification_missing_filters'';end if;\n if cat=''program'' then\n if d->''delivery''->>''value'' is distinct from (case f->>''delivery'' when ''offline'' then ''onsite'' when ''hybrid'' then ''mixed'' else ''online'' end) or\n d->''application''->''value''->>''deadlineKind'' is distinct from (case when f->>''deadlineKind''=''closed'' then ''none'' else f->>''deadlineKind'' end) or\n f->>''deadlineKind''=''fixed'' and left(d->''application''->''value''->''end''->>''value'',10) is distinct from f->>''deadlineOn'' or\n f->>''deadlineKind''=''closed'' and d->''application''->''value''->>''sourceStatus''<>''closed'' then raise sqlstate ''PT422'' using message=''classification_inconsistent_filters'';end if;\n end if;\n if cat=''event'' then\n if f->>''delivery''=''online'' then raise sqlstate ''PT422'' using message=''classification_event_venue_required'';end if;\n for o in select value from jsonb_array_elements(d->''schedule''->''value''->''occurrences'') loop\n start_day:=left(o->''start''->>''value'',10);end_day:=left(o->''end''->>''value'',10);\n if start_day<f->>''eventStart'' or end_day>f->>''eventEnd'' then raise sqlstate ''PT422'' using message=''classification_schedule_outside_period'';end if;end loop;\n end if;\n elsif d is not null then raise sqlstate ''PT422'' using message=''classification_unexpected_filters'';end if;\nend $function$\n", "machimoa_review.classification_reasons(uuid,jsonb)": "CREATE OR REPLACE FUNCTION machimoa_review.classification_reasons(p_id uuid, f jsonb)\n RETURNS text[]\n LANGUAGE plpgsql\n STABLE\n SET search_path TO ''''\nAS $function$\ndeclare s machimoa_review.source_items%rowtype;pf machimoa_review.source_item_program_facts%rowtype;r jsonb;codes text[];g jsonb;\nbegin\n select * into s from machimoa_review.source_items where id=p_id;\n select * into pf from machimoa_review.source_item_program_facts where source_item_id=p_id and revision_hash=s.revision_hash;\n if pf.source_item_id is not null then\n r:=case when s.source_id=''myseoul_program'' then machimoa_review.myseoul_evaluate(pf.facts,statement_timestamp()) else machimoa_review.program_evaluate(pf.facts,statement_timestamp()) end;\n if pf.manual_excluded or r->>''decision''=''out_of_scope'' then return array[''classification_source_excluded''];end if;\n select array(select code from jsonb_array_elements_text(coalesce(r->''reasons'',''[]'')) code where not (machimoa_review.publication_temporal_ready(r) and code in (''application_not_started'',''application_closed'',''operation_ended'',''not_currently_accepting'',''program_ended'')) and code not in\n (''category_unresolved'',''delivery_mode_unknown'',''activity_region_unknown'',''application_period_unknown'',''operation_period_unknown'',''application_state_unknown'',''online_residence_unknown'') and code not like ''content_filter:%'') into codes;\n else codes:=''{}'';end if;\n if f->>''productType'' not in (''event_program'',''policy_reference'',''living_guide'') then return array_append(codes,''classification_missing_facts'');end if;\n select to_jsonb(gate) into g from machimoa_review.evaluate_source_item_gates(s.body_usable,s.has_source_url,s.attachment_present,f->>''productType'',''{}'',machimoa_review.classification_gate(f)) gate;\n codes:=codes||array(select code from jsonb_array_elements(coalesce(g->''jobs'',''[]'')) job cross join lateral jsonb_array_elements_text(job->''reason_codes'') code);\n if g->>''disposition''<>''target'' and cardinality(codes)=0 then codes:=array_append(codes,''classification_scope_unresolved'');end if;\n return array(select distinct c from unnest(codes) c);\nend $function$\n"}'::jsonb);
CREATE OR REPLACE FUNCTION machimoa_review.classification_validate(f jsonb, d jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare cat text;key text;g jsonb;o jsonb;start_day text;end_day text;
begin
 if f is null or jsonb_typeof(f)<>'object' or (select array_agg(k order by k) from jsonb_object_keys(f) k) is distinct from array['category','deadlineKind','deadlineOn','delivery','eventEnd','eventStart','evidence','foreignEligibility','productType','regions','scope'] then raise sqlstate 'PT422' using message='classification_invalid_facts';end if;
 foreach key in array array['category','deadlineKind','deadlineOn','delivery','eventEnd','eventStart','evidence','foreignEligibility','productType','scope'] loop
 if jsonb_typeof(f->key)<>'string' or f->>key ~ '[<>]' then raise sqlstate 'PT422' using message='classification_invalid_text';end if;end loop;
 cat:=f->>'category';
 if cat not in ('policy','program','event','youth_space','living') or f->>'productType' not in ('event_program','policy_reference','living_guide') or f->>'delivery' not in ('online','offline','hybrid') or f->>'scope' not in ('nationwide','specific','unknown') or f->>'foreignEligibility' not in ('eligible','ineligible','unknown') or char_length(f->>'evidence')>500 then raise sqlstate 'PT422' using message='classification_missing_facts';end if;
 if jsonb_typeof(f->'regions')<>'array' or jsonb_array_length(f->'regions')>17 or exists(select 1 from jsonb_array_elements(f->'regions') v where jsonb_typeof(v)<>'string' or v#>>'{}' not in ('11','26','27','28','29','30','31','36','41','42','43','44','45','46','47','48','50')) or (select count(distinct v) from jsonb_array_elements(f->'regions') v)<>jsonb_array_length(f->'regions') then raise sqlstate 'PT422' using message='classification_invalid_regions';end if;
 if f->>'scope'<>'specific' and jsonb_array_length(f->'regions')<>0 or f->>'scope'='specific' and jsonb_array_length(f->'regions')=0 then raise sqlstate 'PT422' using message='classification_invalid_regions';end if;
 if f->>'productType'<>'living_guide' and not (f->>'productType'='event_program' and cat in ('program','event','youth_space') and f->>'delivery' in ('offline','hybrid') and (cat<>'youth_space' or d->'spaceKind'->>'value' is distinct from 'news')) and (f->>'scope'='unknown' or char_length(btrim(f->>'evidence'))=0) or f->>'productType'='policy_reference' and f->>'foreignEligibility'='unknown' then raise sqlstate 'PT422' using message='classification_missing_evidence';end if;
 g:=machimoa_review.classification_gate(f);perform machimoa_review.validate_gate_facts(f->>'productType',g);
 if cat='program' and f->>'deadlineKind' is distinct from 'fixed' then raise sqlstate 'PT422' using message='classification_invalid_dates';end if;
 if cat in ('policy','program') then
 if f->>'deadlineKind' not in ('fixed','none','closed') or f->>'eventStart'<>'' or f->>'eventEnd'<>'' then raise sqlstate 'PT422' using message='classification_invalid_dates';end if;
 if f->>'deadlineKind'='fixed' then perform machimoa_review.content_filter_day(f->>'deadlineOn');elsif f->>'deadlineOn'<>'' then raise sqlstate 'PT422' using message='classification_invalid_dates';end if;
 elsif cat='event' then
 perform machimoa_review.content_filter_day(f->>'eventStart');perform machimoa_review.content_filter_day(f->>'eventEnd');
 if f->>'eventStart'>f->>'eventEnd' or f->>'deadlineKind'<>'' or f->>'deadlineOn'<>'' then raise sqlstate 'PT422' using message='classification_invalid_dates';end if;
 elsif f->>'deadlineKind'<>'' or f->>'deadlineOn'<>'' or f->>'eventStart'<>'' or f->>'eventEnd'<>'' then raise sqlstate 'PT422' using message='classification_invalid_dates';end if;
 if cat in ('program','event','youth_space') then
 perform machimoa_review.content_filter_validate(d);
 if d->>'category' is distinct from cat or cardinality(machimoa_review.classification_filter_missing(d))<>0 then raise sqlstate 'PT422' using message='classification_missing_filters';end if;
 if cat='program' then
 if d->'delivery'->>'value' is distinct from (case f->>'delivery' when 'offline' then 'onsite' when 'hybrid' then 'mixed' else 'online' end) or
 d->'application'->'value'->>'deadlineKind' is distinct from (case when f->>'deadlineKind'='closed' then 'none' else f->>'deadlineKind' end) or
 f->>'deadlineKind'='fixed' and left(d->'application'->'value'->'end'->>'value',10) is distinct from f->>'deadlineOn' or
 f->>'deadlineKind'='closed' and d->'application'->'value'->>'sourceStatus'<>'closed' then raise sqlstate 'PT422' using message='classification_inconsistent_filters';end if;
 end if;
 if cat='event' then
 if f->>'delivery'='online' then raise sqlstate 'PT422' using message='classification_event_venue_required';end if;
 for o in select value from jsonb_array_elements(d->'schedule'->'value'->'occurrences') loop
 start_day:=left(o->'start'->>'value',10);end_day:=left(o->'end'->>'value',10);
 if start_day<f->>'eventStart' or end_day>f->>'eventEnd' then raise sqlstate 'PT422' using message='classification_schedule_outside_period';end if;end loop;
 end if;
 elsif d is not null then raise sqlstate 'PT422' using message='classification_unexpected_filters';end if;
end $function$
;

CREATE OR REPLACE FUNCTION machimoa_review.classification_reasons(p_id uuid, f jsonb)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare s machimoa_review.source_items%rowtype;pf machimoa_review.source_item_program_facts%rowtype;r jsonb;codes text[];g jsonb;d jsonb;venue_mode boolean;venue_ready boolean:=false;
begin
 select * into s from machimoa_review.source_items where id=p_id;
 select * into pf from machimoa_review.source_item_program_facts where source_item_id=p_id and revision_hash=s.revision_hash;
 if pf.source_item_id is not null then
 r:=case when s.source_id='myseoul_program' then machimoa_review.myseoul_evaluate(pf.facts,statement_timestamp()) else machimoa_review.program_evaluate(pf.facts,statement_timestamp()) end;
 if pf.manual_excluded or r->>'decision'='out_of_scope' then return array['classification_source_excluded'];end if;
 select array(select code from jsonb_array_elements_text(coalesce(r->'reasons','[]')) code where not (machimoa_review.publication_temporal_ready(r) and code in ('application_not_started','application_closed','operation_ended','not_currently_accepting','program_ended')) and code not in
 ('category_unresolved','delivery_mode_unknown','activity_region_unknown','application_period_unknown','operation_period_unknown','application_state_unknown','online_residence_unknown') and code not like 'content_filter:%') into codes;
 else codes:='{}';end if;
 if f->>'productType' not in ('event_program','policy_reference','living_guide') then return array_append(codes,'classification_missing_facts');end if;
 select to_jsonb(gate) into g from machimoa_review.evaluate_source_item_gates(s.body_usable,s.has_source_url,s.attachment_present,f->>'productType','{}',machimoa_review.classification_gate(f)) gate;
 select filters into d from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=s.revision_hash;
 if (d is null or d->>'category' is distinct from f->>'category') and f->>'category' in ('program','event','youth_space') then d:=machimoa_review.classification_draft(p_id,f->>'category')->'filters';end if;
 venue_mode:=f->>'productType'='event_program' and f->>'category' in ('program','event','youth_space') and f->>'delivery' in ('offline','hybrid') and (f->>'category'<>'youth_space' or d->'spaceKind'->>'value' is distinct from 'news');
 if venue_mode then
 select filters into d from machimoa_review.review_classifications where source_item_id=p_id and revision_hash=s.revision_hash;
 if d is null or d->>'category' is distinct from f->>'category' then d:=machimoa_review.classification_draft(p_id,f->>'category')->'filters';end if;
 venue_ready:=d->'location'->>'status'='known' and (d->'location'->'value'->>'scope'='nationwide' or d->'location'->'value'->>'scope'='specific' and jsonb_array_length(d->'location'->'value'->'venues')>0 and not exists(select 1 from jsonb_array_elements(d->'location'->'value'->'venues') x where x->>'province' not in ('11','28','41')));
 if coalesce(venue_ready,false) is not true then codes:=array_append(codes,'activity_region_unknown');end if;
 end if;
 codes:=codes||array(select code from jsonb_array_elements(coalesce(g->'jobs','[]')) job cross join lateral jsonb_array_elements_text(job->'reason_codes') code where not (venue_mode and coalesce(venue_ready,false) and code='region_scope_unknown'));
 if g->>'disposition'<>'target' and cardinality(codes)=0 and not (venue_mode and coalesce(venue_ready,false) and g->>'disposition'='region_review_required' and g->>'region_status'='review_required' and g->>'audience_status'='not_applicable') then codes:=array_append(codes,'classification_scope_unresolved');end if;
 return array(select distinct c from unnest(codes) c);
end $function$
;

create function machimoa_review.classification_flow_dirty() returns trigger language plpgsql set search_path='' as $$begin update machimoa_review.classification_flow_install set dirty=true where singleton=true;return null;end $$;
revoke all on function machimoa_review.classification_flow_dirty() from public,anon,authenticated,service_role;
create trigger classification_flow_dirty after insert or update or delete on machimoa_review.review_classifications for each statement execute function machimoa_review.classification_flow_dirty();
create trigger classification_flow_dirty after insert or update or delete on machimoa_review.review_classification_history for each statement execute function machimoa_review.classification_flow_dirty();
create trigger classification_flow_dirty after insert or update or delete on machimoa_review.source_item_content_filters for each statement execute function machimoa_review.classification_flow_dirty();
create trigger classification_flow_dirty after insert or update or delete on machimoa_review.source_item_program_facts for each statement execute function machimoa_review.classification_flow_dirty();
create trigger classification_flow_dirty after insert or update or delete on machimoa_review.myseoul_residence_reviews for each statement execute function machimoa_review.classification_flow_dirty();
create trigger classification_flow_dirty after insert or update or delete on machimoa_review.myseoul_fact_edits for each statement execute function machimoa_review.classification_flow_dirty();
commit;
